    "content": "name: remote_pc_client\ndescription: \"High-performance Remote PC Controller & Screen Mirroring Android Client\"\npublish_to: \"none\"\nversion: 1.0.0+1\n\nenvironment:\n  sdk: \">=3.0.0 <4.0.0\"\n  flutter: \">=3.16.0\"\n\ndependencies:\n  flutter:\n    sdk: flutter\n  web_socket_channel: ^3.0.1\n  cupertino_icons: ^1.0.8\n\ndev_dependencies:\n  flutter_test:\n    sdk: flutter\n  flutter_lints: ^4.0.0\n\nflutter:\n  uses-material-design: true\n"
